<script setup>
import { ref, reactive, onMounted, watch } from 'vue'
import { useRouter } from 'vue-router'
import { UserRound, Bookmark, CalendarDays, Settings, Check, LogOut, LockKeyhole, LogIn } from 'lucide-vue-next'
import { authRequest, state, notify, money, dateText, niceTime } from '../lib/state'
import WorkshopGrid from '../components/WorkshopGrid.vue'
const router=useRouter(), bookings=ref([]),favorites=ref([]),editing=ref(false),busy=ref(false)
const p=reactive({ name:'', budget:80,district:'Miraflores',interests:[],day:'' })
function fill(){if(!state.user)return;Object.assign(p,{name:state.user.name,budget:state.user.preferences?.budget??80,district:state.user.preferences?.district??'Miraflores',interests:[...(state.user.preferences?.interests||[])],day:state.user.preferences?.day||''})}
async function load(){if(!state.user)return;fill();try{const [b,f]=await Promise.all([authRequest('/me/bookings'),authRequest('/me/favorites')]);bookings.value=b.items;favorites.value=f.items}catch(e){notify(e.message)}}
onMounted(load)
watch(()=>state.user?.id,load)
async function save(){try{busy.value=true;const resp=await authRequest('/me',{method:'PATCH',body:{name:p.name,preferences:{budget:Number(p.budget),district:p.district,interests:p.interests,day:p.day}}});state.user=resp.user;editing.value=false;notify('Perfil y preferencias actualizados')}catch(e){notify(e.message)}finally{busy.value=false}}
</script>
<template><div class="page profile-page"><div class="profile-banner"><span class="avatar big">{{state.user?.name?.slice(0,1)??'A'}}</span><div><h1>{{state.user?.name}}</h1><p>Explorador · {{state.user?.preferences?.district||'Miraflores'}}</p><span class="small muted">Cuenta de {{state.user?.role==='client'?'cliente':'tallerista'}}</span></div><button class="btn outline" @click="editing=!editing"><Settings :size="16"/> {{editing?'Cancelar':'Editar preferencias'}}</button></div>
  <section v-if="editing" class="form-card"><h2>Mis preferencias</h2><form @submit.prevent="save" class="pref-form"><label>Nombre<input v-model="p.name" required minlength="2"/></label><label>Presupuesto máximo (S/)<input v-model.number="p.budget" type="number" min="0" max="9999"/></label><label>Mi distrito<select v-model="p.district"><option v-for="d in state.meta.districts" :key="d">{{d}}</option></select></label><label>Día preferido<select v-model="p.day"><option value="">Indistinto</option><option value="sábado">Sábado</option><option value="domingo">Domingo</option><option value="lunes">Lunes</option><option value="martes">Martes</option><option value="miércoles">Miércoles</option><option value="jueves">Jueves</option><option value="viernes">Viernes</option></select></label><div class="span-all"><b>Intereses</b><div class="interest-list"><label v-for="cat in state.meta.categories" :key="cat" class="interest"><input type="checkbox" :value="cat" v-model="p.interests"/>{{cat}}</label></div></div><button class="btn primary" :disabled="busy">Guardar preferencias</button></form></section>
  <section class="profile-section"><div class="section-heading"><h2>Mis reservas</h2><RouterLink to="/agenda" class="btn outline sm">Ver mi agenda</RouterLink><span class="muted">{{bookings.length}} registradas</span></div><div v-if="!bookings.length" class="empty compact">Aún no tienes reservas. <RouterLink to="/explorar" class="text-link">Explorar talleres →</RouterLink></div><div class="booking-list"><RouterLink v-for="b in bookings" :key="b.id" :to="`/taller/${b.workshopId}`" class="booking-item"><img :src="b.workshop?.image" :alt="b.workshop?.title"/><div><b>{{b.workshop?.title}}</b><p class="muted">{{dateText(b.workshop?.date)}} · {{niceTime(b.workshop?.startsAt)}}</p><p class="muted">{{b.seats}} cupo(s) · {{money(b.workshop?.price*b.seats)}} · cód. {{b.id.slice(0,8).toUpperCase()}}</p></div><span class="status-chip">{{b.status}}</span></RouterLink></div></section>
  <section class="profile-section"><div class="section-heading"><h2>Talleres guardados</h2><RouterLink to="/guardados" class="text-link">Ver todos →</RouterLink></div><WorkshopGrid :items="favorites.slice(0,3)" @favorite-changed="load"/></section>
  <section class="form-card"><p class="muted">Tu sesión y contraseña se gestionan en Mi cuenta. ¿Nos ayudas a mejorar? Cuéntanos qué te pareció Hobbiz.</p><RouterLink to="/cuenta" class="btn outline">Ir a Mi cuenta</RouterLink> <RouterLink to="/opinion" class="btn primary">Dar mi opinión</RouterLink></section></div></template>
